        if(kind==Kind.HARVEST){if(!action.getAllKeys().equals(Set.of("Type","Receipt"))||!action.getString("Type").equals("HARVEST")||!action.contains("Receipt",Tag.TAG_COMPOUND)||!before.isEmpty()||!after.isEmpty())throw new IllegalArgumentException("Malformed root-only harvest recipe");var receipt=NativeGearHarvestReceipt.read(registries,root.getBlockPos(),action.getCompound("Receipt"));if(!receipt.sourceMatches(root.payload()))throw new IllegalArgumentException("Harvest captured owner changed");var expected=root.payload().withoutCell(receipt.cell);if(!Objects.equals(expected==null?null:expected.write(),payload==null?null:payload.write())||!NativeGearStoredSections.write(root.sections(),root.identity()).equals(NativeGearStoredSections.write(sections,root.identity())))throw new IllegalArgumentException("Harvest must remove exactly its selected cell");return;}
